#include<stdio.h>
int main()
{
    printf("Enter a number, not blank. ");
    scanf("%d",&num);
    int colors[4],item;
    for(int i=0;i<4;i++){
        colors[i]=0;
    }
    for(int i=0;i<num;i++){
        for(item=0;item<4;item++){
            colors[item]+=colors[item];
        }
    }

