#include <stdio.h>
int main()
{
	char letter;
	int number;
	char numberStr[100];

	while (getchar() != EOF) {
		number = getchar()-47;
		letter = '\0';
		for (int i=0; i<100; i++) {
			numberStr[i] = letter;
		}
		printf("%c%c",letter,number);
		letter = getchar();
	}
